import * as React from "react"
import { ArrowLeft, Copy, Check, House, LifeBuoy, RefreshCw } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Result, type ResultStatus } from "@/components/ui/result"

export type ErrorPageStatus = Extract<ResultStatus, "403" | "404" | "500">

export interface ErrorPageProps {
  status: ErrorPageStatus
  /** Override the default title / description of the status. */
  title?: React.ReactNode
  description?: React.ReactNode
  /** Requested path, shown for 404 / 403 so the user can spot a typo. */
  path?: string
  /** Support reference of a server error (500); shown with a copy button so users can quote it. */
  errorId?: string
  onHome?: () => void
  onBack?: () => void
  /** 500: try the same request again. */
  onRetry?: () => void
  /** 403: ask for access (opens a request form in the app). */
  onRequestAccess?: () => void
  /** Contact / report a problem. */
  onSupport?: () => void
  className?: string
}

const text = {
  "404": { title: "Không tìm thấy trang", description: "Địa chỉ có thể đã sai, hoặc trang đã được chuyển hoặc xóa." },
  "403": { title: "Bạn chưa có quyền truy cập", description: "Tài khoản hiện tại không được phép xem nội dung này. Nếu cần, hãy gửi yêu cầu cấp quyền." },
  "500": { title: "Hệ thống đang gặp sự cố", description: "Đã có lỗi ở phía máy chủ. Hãy thử lại sau ít phút; nếu vẫn lỗi, báo cho bộ phận hỗ trợ kèm mã lỗi." },
} as const

/** Full-page 403 / 404 / 500 with the recovery actions that make sense for each: home, back, retry, request access, contact support. */
export function ErrorPage({ status, title, description, path, errorId, onHome, onBack, onRetry, onRequestAccess, onSupport, className }: ErrorPageProps) {
  const [copied, setCopied] = React.useState(false)
  const copy = async () => {
    try { await navigator.clipboard.writeText(errorId ?? ""); setCopied(true); setTimeout(() => setCopied(false), 1800) } catch { /* clipboard not available */ }
  }
  return (
    <main data-slot="error-page" data-status={status} className={className ?? "grid h-full min-h-0 w-full place-items-center overflow-y-auto bg-background px-4 py-10"}>
      <Result
        status={status}
        headingLevel={1}
        title={title ?? text[status].title}
        subTitle={<>{description ?? text[status].description}{path && <span className="mt-2 block text-small">Địa chỉ: <code className="font-mono text-foreground">{path}</code></span>}</>}
        extra={<>
          {onHome && <Button onClick={onHome}><House />Về trang chủ</Button>}
          {status === "500" && onRetry && <Button variant="outline" onClick={onRetry}><RefreshCw />Thử lại</Button>}
          {status === "403" && onRequestAccess && <Button variant="outline" onClick={onRequestAccess}>Yêu cầu cấp quyền</Button>}
          {onBack && <Button variant="ghost" onClick={onBack}><ArrowLeft />Quay lại</Button>}
          {onSupport && <Button variant="ghost" onClick={onSupport}><LifeBuoy />Liên hệ hỗ trợ</Button>}
        </>}
      >
        {errorId && (
          <div className="flex items-center justify-between gap-3 text-small">
            <span className="text-muted-foreground">Mã lỗi: <code className="font-mono text-foreground">{errorId}</code></span>
            <Button variant="ghost" size="sm" onClick={copy} aria-label="Sao chép mã lỗi">{copied ? <Check /> : <Copy />}{copied ? "Đã chép" : "Sao chép"}</Button>
          </div>
        )}
      </Result>
    </main>
  )
}

"use client"

// @dthu/ui 0.2.0 · block-system
import * as React from "react"
import { ArrowLeft } from "lucide-react"
import { Button } from "@/components/ui/button"

export interface LegalSection { id: string; title: string; body: React.ReactNode }

export interface LegalPageProps {
  /** "Điều khoản sử dụng", "Chính sách bảo mật"... */
  title: string
  /** Display text such as "Có hiệu lực từ 01/10/2026". */
  effective?: string
  version?: string
  /** Short intro under the title. */
  intro?: React.ReactNode
  sections: LegalSection[]
  /** Brand block at the top of the page. */
  brand?: React.ReactNode
  onBack?: () => void
  /** Consent mode: shows "Tôi đã đọc và đồng ý" and calls this when pressed. */
  onAccept?: () => void
  /** Label of the consent button. */
  acceptLabel?: string
  className?: string
}

/** Terms / privacy / policy page: sticky table of contents (anchors), numbered sections, and an optional consent footer. */
export function LegalPage({ title, effective, version, intro, sections, brand, onBack, onAccept, acceptLabel = "Tôi đã đọc và đồng ý", className }: LegalPageProps) {
  const [agree, setAgree] = React.useState(false)
  return (
    <div data-slot="legal-page" className={className ?? "h-full min-h-0 w-full overflow-y-auto bg-background text-foreground"}>
      <div className="mx-auto grid max-w-[1040px] grid-cols-[220px_minmax(0,1fr)] gap-x-12 px-6 py-8 max-md:grid-cols-1 max-sm:px-4">
        <header className="col-span-full mb-6 border-b border-border pb-5">
          {brand && <div className="mb-4">{brand}</div>}
          {onBack && <Button variant="ghost" size="sm" className="-ml-2 mb-2" onClick={onBack}><ArrowLeft />Quay lại</Button>}
          <h1 className="m-0 text-[28px] font-bold tracking-[-0.01em]">{title}</h1>
          {(effective || version) && <p className="m-0 mt-1 text-small text-muted-foreground">{[effective, version && `Phiên bản ${version}`].filter(Boolean).join(" · ")}</p>}
          {intro && <p className="m-0 mt-3 max-w-[68ch] text-body text-muted-foreground">{intro}</p>}
        </header>
        <nav aria-label="Mục lục" className="sticky top-4 self-start max-md:hidden">
          <ol className="m-0 grid list-none gap-0.5 border-l border-border p-0">
            {sections.map((s, i) => <li key={s.id}><a href={`#${s.id}`} className="-ml-px block border-l-2 border-transparent py-1 pl-3 text-small text-muted-foreground no-underline outline-none hover:border-primary hover:text-foreground focus-visible:shadow-focus">{i + 1}. {s.title}</a></li>)}
          </ol>
        </nav>
        <article className="min-w-0">
          {sections.map((s, i) => (
            <section key={s.id} id={s.id} aria-labelledby={`${s.id}-h`} className="mb-8 scroll-mt-4">
              <h2 id={`${s.id}-h`} className="m-0 mb-2 text-xl font-bold">{i + 1}. {s.title}</h2>
              <div className="grid max-w-[72ch] gap-3 text-body leading-relaxed text-foreground [&_ul]:m-0 [&_ul]:list-disc [&_ul]:pl-5">{s.body}</div>
            </section>
          ))}
          {onAccept && (
            <div className="sticky bottom-0 -mx-1 flex flex-wrap items-center justify-between gap-3 border-t border-border bg-background px-1 py-4">
              <label className="m-0 flex cursor-pointer items-center gap-2 text-body"><input type="checkbox" checked={agree} onChange={(e) => setAgree(e.target.checked)} className="m-0 size-4 accent-primary" />{acceptLabel}</label>
              <Button disabled={!agree} onClick={onAccept}>Tiếp tục</Button>
            </div>
          )}
        </article>
      </div>
    </div>
  )
}

import * as React from "react"
import { Mail, Phone, RefreshCw, Wrench } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Progress } from "@/components/ui/progress"
import { Result } from "@/components/ui/result"

export interface MaintenancePageProps {
  title?: React.ReactNode
  message?: React.ReactNode
  /** Display text such as "22:00, 24/10/2026". */
  startsAt?: string
  endsAt?: string
  /** 0-100. Shows a progress bar while maintenance is running. */
  progress?: number
  /** Support contacts. */
  phone?: string
  email?: string
  /** "Kiểm tra lại" - the app re-checks the health endpoint. */
  onRetry?: () => void
  retrying?: boolean
  className?: string
}

/** Planned-maintenance screen: window, optional progress, contacts and a re-check button. Serve it from the gateway so it works when the app is down. */
export function MaintenancePage({ title = "Hệ thống đang bảo trì", message = "Chúng tôi đang nâng cấp để phục vụ tốt hơn. Dữ liệu của bạn vẫn được giữ nguyên.", startsAt, endsAt, progress, phone, email, onRetry, retrying, className }: MaintenancePageProps) {
  return (
    <main data-slot="maintenance-page" className={className ?? "grid h-full min-h-0 w-full place-items-center overflow-y-auto bg-background px-4 py-10"}>
      <Result status="info" headingLevel={1} icon={<span aria-hidden className="grid size-20 place-items-center rounded-full bg-accent text-primary"><Wrench className="size-9" strokeWidth={1.6} /></span>} title={title} subTitle={message}
        extra={onRetry && <Button onClick={onRetry} disabled={retrying}><RefreshCw className={retrying ? "animate-spin" : undefined} />{retrying ? "Đang kiểm tra..." : "Kiểm tra lại"}</Button>}>
        <div className="grid gap-3 text-body">
          {(startsAt || endsAt) && (
            <dl className="m-0 grid gap-2">
              {startsAt && <div className="flex justify-between gap-4"><dt className="text-muted-foreground">Bắt đầu</dt><dd className="m-0 font-medium">{startsAt}</dd></div>}
              {endsAt && <div className="flex justify-between gap-4"><dt className="text-muted-foreground">Dự kiến xong</dt><dd className="m-0 font-medium">{endsAt}</dd></div>}
            </dl>
          )}
          {progress != null && <div className="grid gap-1.5"><div className="flex justify-between"><span className="text-muted-foreground">Tiến độ</span><span className="font-medium tabular-nums">{Math.round(progress)}%</span></div><Progress value={progress} aria-label="Tiến độ bảo trì" /></div>}
          {(phone || email) && (
            <div className="flex flex-wrap gap-x-5 gap-y-1 border-t border-border pt-3 text-small text-muted-foreground">
              {phone && <a className="inline-flex items-center gap-1.5 text-primary hover:underline" href={`tel:${phone.replace(/\s/g, "")}`}><Phone aria-hidden className="size-3.5" />{phone}</a>}
              {email && <a className="inline-flex items-center gap-1.5 text-primary hover:underline" href={`mailto:${email}`}><Mail aria-hidden className="size-3.5" />{email}</a>}
            </div>
          )}
        </div>
      </Result>
    </main>
  )
}

